package cn.zhuatech.pricingai.controller; import cn.zhuatech.pricingai.common.ApiResponse; import cn.zhuatech.pricingai.dto.PricingAiDto.*; import cn.zhuatech.pricingai.service.PricingAiService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOMAIN_OPERATOR','QUALITY','ADMIN')") public class OperationsAdminController {private final PricingAiService service;public OperationsAdminController(PricingAiService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkRecordView>> orders(){return ApiResponse.ok(service.workRecords());}}
